import{_ as n,a0 as o,w as i,s as d,ao as p,I as r,x as l,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"2020 年將是 SD-WAN 的回顧之年 | LCTT x X-CMD","titleTemplate":false,"description":"2020 年將是 SD-WAN 的回顧之年 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"2020 年將是 SD-WAN 的回顧之年 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2020 年將是 SD-WAN 的回顧之年 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200310 2020 Will Be a Year of Hindsight for SD-WAN","title":"2020 年將是 SD-WAN 的回顧之年","tag":"202003","desc":""},"relativePath":"202003/20200310 2020 Will Be a Year of Hindsight for SD-WAN.md","filePath":"[post].md"}'),f={name:"202003/20200310 2020 Will Be a Year of Hindsight for SD-WAN.md"};function u(m,t,w,N,A,W){const s=o("Link");return i(),d("div",null,[t[33]||(t[33]=p('<h1 id="_2020-年將是-sd-wan-的回顧之年" tabindex="-1">2020 年將是 SD-WAN 的回顧之年 <a class="header-anchor" href="#_2020-年將是-sd-wan-的回顧之年" aria-label="Permalink to “2020 年將是 SD-WAN 的回顧之年”">​</a></h1><p><img src="https://images.idgesg.net/images/article/2020/03/istock-1127447341-100834720-large.jpg" alt=""></p><p>對於軟件定義的廣域網（SD-WAN），“過去看起來困難的選擇，知道了這些選擇的結果後，現在看起來就很清晰了” 這一説法再合適不過了。總結過去的幾年：雲計算和數字化轉型促使公司重新評估傳統的 WAN 技術，該技術不再能夠滿足其不斷增長的業務需求。從那時起，SD-WAN 成為一種有前途的新技術。</p><p>SD-WAN 旨在解決物理設備的流量管理問題，並支持從雲進行基於軟件的配置。許多最初的 SD-WAN 部署都因希望取代昂貴的多協議標籤交換 （MPLS） 而得到推動。公司希望它可以神奇地解決他們所有的網絡問題。但是在實踐中，基本的 SD-WAN 解決方案遠沒有實現這一願景。</p><p>快速發展到現在，圍繞 SD-WAN 的炒作已經塵埃落定，並且早期的實施工作已經過去。現在是時候回顧一下我們在 2019 年學到的東西以及在 2020 年要改進的地方。所以，讓我們開始吧。</p><h3 id="_1、這與節省成本無關" tabindex="-1">1、這與節省成本無關 <a class="header-anchor" href="#_1、這與節省成本無關" aria-label="Permalink to “1、這與節省成本無關”">​</a></h3>',6)),r("p",null,[t[1]||(t[1]=l("大多數公司選擇 SD-WAN 作為 MPLS 的替代品，因為它可以降低 WAN 成本。但是，",-1)),e(s,{href:"https://blog.silver-peak.com/to-maximize-the-value-of-sd-wan-look-past-hardware-savings"},{default:a(()=>[...t[0]||(t[0]=[l("節省的成本",-1)])]),_:1}),t[2]||(t[2]=l("會因 SD-WAN 的不同而異，因此不應將其用作部署該技術的主要驅動力。無論公司需要什麼，公司都應該專注於提高網絡敏捷性，例如實現更快的站點部署和減少配置時間。SD-WAN 的主要驅動力是使網絡更高效。如果成功實現那麼成本也會隨之降低。",-1))]),t[34]||(t[34]=r("h3",{id:"_2、wan-優化是必要的",tabindex:"-1"},[l("2、WAN 優化是必要的 "),r("a",{class:"header-anchor",href:"#_2、wan-優化是必要的","aria-label":"Permalink to “2、WAN 優化是必要的”"},"​")],-1)),r("p",null,[t[4]||(t[4]=l("説到效率，",-1)),e(s,{href:"https://blog.silver-peak.com/sd-wan-vs-wan-optimization"},{default:a(()=>[...t[3]||(t[3]=[l("WAN 優化",-1)])]),_:1}),t[5]||(t[5]=l("提高了應用程序和數據流量的性能。通過應用協議加速、重複數據消除、壓縮和緩存等技術，WAN 優化可以增加帶寬、減少延遲並減輕數據包丟失。最初的想法是 SD-WAN 可以完成對 WAN 優化的需求，但是我們現在知道某些應用程序需要更多的性能支持。這些技術相互補充，而不是相互替代。它們應該用來解決不同的問題。",-1))]),t[35]||(t[35]=r("h3",{id:"_3、安全性不應該事後考慮",tabindex:"-1"},[l("3、安全性不應該事後考慮 "),r("a",{class:"header-anchor",href:"#_3、安全性不應該事後考慮","aria-label":"Permalink to “3、安全性不應該事後考慮”"},"​")],-1)),r("p",null,[t[7]||(t[7]=l("SD-WAN 具有許多優點，其中之一就是使用寬帶互聯網快速發送企業應用程序流量。但是這種方法也帶來了安全風險，因為它使用户及其本地網絡暴露於不受信任的公共互聯網中。從一開始，安全性就應該成為 SD-WAN 實施的一部分，而不是在事後。公司可以通過使用",-1)),e(s,{href:"https://blog.silver-peak.com/sd-wans-enable-scalable-local-internet-breakout-but-pose-security-risk"},{default:a(()=>[...t[6]||(t[6]=[l("安全的雲託管",-1)])]),_:1}),t[8]||(t[8]=l("之類的服務，將安全性放在分支機構附近，從而實現所需的應用程序性能和保護。",-1))]),t[36]||(t[36]=r("h3",{id:"_4、可見性對於-sd-wan-成功至關重要",tabindex:"-1"},[l("4、可見性對於 SD-WAN 成功至關重要 "),r("a",{class:"header-anchor",href:"#_4、可見性對於-sd-wan-成功至關重要","aria-label":"Permalink to “4、可見性對於 SD-WAN 成功至關重要”"},"​")],-1)),r("p",null,[t[10]||(t[10]=l("在應用程序和數據流量中具有",-1)),e(s,{href:"https://blog.silver-peak.com/know-the-true-business-drivers-for-sd-wan"},{default:a(()=>[...t[9]||(t[9]=[l("可見性",-1)])]),_:1}),t[11]||(t[11]=l("，這使網絡管理不再需要猜測。最好的起點是部署前階段，在此階段，公司可以在實施 SD-WAN 之前評估其現有功能以及缺少的功能。可見性以日常監控和警報的形式在部署後繼續發揮重要作用。瞭解網絡中正在發生的情況的公司會更好地準備應對性能問題，並可以利用這些知識來避免將來出現問題。",-1))]),t[37]||(t[37]=r("h3",{id:"_5、無線廣域網尚未準備就緒",tabindex:"-1"},[l("5、無線廣域網尚未準備就緒 "),r("a",{class:"header-anchor",href:"#_5、無線廣域網尚未準備就緒","aria-label":"Permalink to “5、無線廣域網尚未準備就緒”"},"​")],-1)),r("p",null,[t[13]||(t[13]=l("SD-WAN 可通過包括寬帶和 4G/LTE 無線在內的任何傳輸將用户連接到應用程序。這就是",-1)),e(s,{href:"https://blog.silver-peak.com/mobility-and-sd-wan-part-1-sd-wan-with-4g-lte-is-a-reality"},{default:a(()=>[...t[12]||(t[12]=[l("移動互聯",-1)])]),_:1}),t[14]||(t[14]=l("越來越多地集成到 SD-WAN 解決方案中的原因。儘管公司渴望將 4G 用作潛在的傳輸替代方案（尤其是在偏遠地區），但由此帶來的按使用付費 4G 服務成本卻很高。此外，由於延遲和帶寬限制，4G 可能會出現問題。最好的方法是等待服務提供商部署具有更好的價格選擇的 5G。今年我們將看到 5G 的推出，並更加關注無線 SD-WAN。",-1))]),r("p",null,[t[16]||(t[16]=l("請務必觀看以下 SD-WAN 視頻系列：",-1)),e(s,{href:"https://www.silver-peak.com/everything-you-need-to-know-about-sd-wan"},{default:a(()=>[...t[15]||(t[15]=[l("你應該知道的所有關於 SD-WAN 的知識",-1)])]),_:1}),t[17]||(t[17]=l("。",-1))]),t[38]||(t[38]=r("hr",null,null,-1)),r("p",null,[t[19]||(t[19]=l("via: ",-1)),e(s,{href:"https://www.networkworld.com/article/3531315/2020-will-be-a-year-of-hindsight-for-sd-wan.html"},{default:a(()=>[...t[18]||(t[18]=[l("https://www.networkworld.com/article/3531315/2020-will-be-a-year-of-hindsight-for-sd-wan.html",-1)])]),_:1})]),r("p",null,[t[24]||(t[24]=l("作者：",-1)),e(s,{href:"https://www.networkworld.com/author/Zeus-Kerravala/"},{default:a(()=>[...t[20]||(t[20]=[l("Zeus Kerravala",-1)])]),_:1}),t[25]||(t[25]=l(" 選題：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[21]||(t[21]=[l("lujun9972",-1)])]),_:1}),t[26]||(t[26]=l(" 譯者：",-1)),e(s,{href:"https://github.com/hkurj"},{default:a(()=>[...t[22]||(t[22]=[l("hkurj",-1)])]),_:1}),t[27]||(t[27]=l(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:a(()=>[...t[23]||(t[23]=[l("wxy",-1)])]),_:1})]),r("p",null,[t[30]||(t[30]=l("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[28]||(t[28]=[l("LCTT",-1)])]),_:1}),t[31]||(t[31]=l(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:a(()=>[...t[29]||(t[29]=[l("Linux中國",-1)])]),_:1}),t[32]||(t[32]=l(" 榮譽推出",-1))])])}const g=n(f,[["render",u]]);export{b as __pageData,g as default};
